const { sum } = require('../src/stats.cjs');
const fmt = (r) => (typeof r === 'bigint' ? r + 'n' : typeof r === 'string' ? JSON.stringify(r) : String(r));
const show = (label, fn) => {
  try { const r = fn(); console.log(label, '=>', fmt(r), `(${typeof r})`); }
  catch (e) { console.log(label, '=> throws', e.constructor.name + ':', e.message); }
};
show('[1,2,3]', () => sum([1, 2, 3]));
show('[]', () => sum([]));
show('[0.1,0.2]', () => sum([0.1, 0.2]));
show('[1,"2",3]', () => sum([1, '2', 3]));
show('["a","b"]', () => sum(['a', 'b']));
show('[1,null]', () => sum([1, null]));
show('[1,undefined]', () => sum([1, undefined]));
show('[1,NaN]', () => sum([1, NaN]));
show('[1,true]', () => sum([1, true]));
show('[1,,3] (hole)', () => sum([1, , 3]));
show('[MAX_SAFE_INTEGER,2]', () => sum([Number.MAX_SAFE_INTEGER, 2]));
show('[1e308,1e308]', () => sum([1e308, 1e308]));
show('[1n,2n]', () => sum([1n, 2n]));
show('Float64Array [1,2]', () => sum(new Float64Array([1, 2])));
show('Set [1,2]', () => sum(new Set([1, 2])));
show('"123"', () => sum('123'));
show('undefined', () => sum());
show('null', () => sum(null));
show('{0:1,length:1}', () => sum({ 0: 1, length: 1 }));
